// Normaliza el registro recuperado de Airtable para inyectarlo en el System Prompt.
// Nunca deja variables vacías y limpia el texto para que no pueda romper los delimitadores del prompt.
const r = $input.first().json;
const f = r.fields ?? r;

const limpiar = (s, max) => String(s ?? '')
  .replace(/CONFIGURACI[ÓO]N DE IDENTIDAD Y MEMORIA DE LARGO PLAZO|FIN DEL CONTEXTO COMPARTIDO/gi, '')
  .replace(/[{}<>`]/g, '')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, max);

const MARCA = '(Historial compactado en Last_Summary)';
const historial = String(f.Historial_Reciente ?? '').trim() === MARCA ? '' : String(f.Historial_Reciente ?? '');

let lastSummary = '';
const raw = String(f.Last_Summary ?? '').trim();
if (raw) {
  try {
    const s = JSON.parse(raw);
    const puntos = Array.isArray(s.puntos_clave) && s.puntos_clave.length ? s.puntos_clave.join('; ') : 'sin puntos clave';
    lastSummary = `Asunto: ${s.asunto_principal}. Puntos clave: ${puntos}. Acción requerida: ${s.accion_requerida}.`;
  } catch (e) {
    lastSummary = raw;
  }
} else if (historial) {
  lastSummary = 'Aún sin resumen. Últimos mensajes: ' + historial.slice(-600);
} else {
  lastSummary = 'La conversación anterior fue muy breve y no dejó contexto relevante.';
}

return [{
  json: {
    session_id: $('Chat Trigger').first().json.sessionId,
    user_name: limpiar(f.User_Name, 60) || 'Cliente que vuelve (todavía no indicó su nombre)',
    last_summary: limpiar(lastSummary, 1200),
    last_summary_raw: raw,
    status: limpiar(f.Status, 40) || 'En curso',
    historial,
    message_count: Number(f.Message_Count ?? 0) || 0,
  },
}];

// Arma el reporte de supervision (texto plano + HTML tipo semaforo) a partir de la ejecucion del agente
const agent = $input.first().json;
const chat = $('Chat Trigger').first().json;
const steps = Array.isArray(agent.intermediateSteps) ? agent.intermediateSteps : [];

const norm = (k) => String(k).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const pick = (obj, names) => {
  const keys = Object.keys(obj || {});
  for (const n of names) {
    const k = keys.find((x) => norm(x) === n);
    if (k && obj[k] !== undefined && obj[k] !== null && String(obj[k]).trim() !== '') return String(obj[k]);
  }
  return 'No informado';
};
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const br = (s) => esc(s).replace(/\n/g, '<br>');

const leadStep = steps.find((s) => /registrar_lead/i.test(s?.action?.tool ?? ''));
let lead = leadStep?.action?.toolInput ?? {};
if (typeof lead === 'string') {
  try { lead = JSON.parse(lead); } catch (e) { lead = {}; }
}
const hasLead = !!leadStep;

const nombre = pick(lead, ['nombre']);
const email = pick(lead, ['email', 'correo electronico', 'correo']);
const telefono = pick(lead, ['telefono']);
const empresa = pick(lead, ['empresa']);
const necesidad = pick(lead, ['necesidad']);
const presupuesto = pick(lead, ['presupuesto']);
const plazo = pick(lead, ['plazo', 'plaza']);
const categoria = pick(lead, ['categoria']);
const puntaje = pick(lead, ['puntaje']);
const escalarLead = pick(lead, ['escalar_a_humano']);
const notas = pick(lead, ['notas']);

const msgUsuario = String(chat.chatInput ?? '');
const emailMsg = (msgUsuario.match(/[^\s@,;]+@[^\s@,;]+\.[^\s@,;]+/) || [])[0] || '';
const telMsg = (msgUsuario.match(/\+?\d[\d\s-]{7,}\d/) || [])[0] || '';
const hayContacto = hasLead || !!emailMsg || !!telMsg || /derivo con una persona/i.test(String(agent.output ?? ''));

const escalatedRaw =
  /^(si|true|verdadero|1)$/i.test(norm(escalarLead)) || ['caliente', 'tibio'].includes(norm(categoria)) ||
  /derivo con una persona/i.test(agent.output ?? '') ||
  /(hablar|conversar|comunicar|contactar).{0,40}(persona|humano|alguien|equipo|ejecutivo|asesor)|reclamo|queja|\bmolest[oa]s?\b|abogad|\blegal/i.test(norm(chat.chatInput ?? ''));
const escalated = escalatedRaw && hayContacto;

const fechaLocal = new Date().toLocaleString('es-CL', { timeZone: 'America/Santiago' });
const linea = '------------------------------';

// ---------- Semaforo por clasificacion ----------
const temas = {
  caliente: { nombre: 'Caliente', emoji: '🔴', color: '#dc2626', dark: '#b91c1c', bg: '#fef2f2', rango: '70 a 100' },
  tibio: { nombre: 'Tibio', emoji: '🟡', color: '#d97706', dark: '#b45309', bg: '#fffbeb', rango: '40 a 69' },
  frio: { nombre: 'Frío', emoji: '🟢', color: '#16a34a', dark: '#15803d', bg: '#f0fdf4', rango: '0 a 39' },
};
const neutro = { nombre: 'Consulta', emoji: '🔵', color: '#2563eb', dark: '#1d4ed8', bg: '#eff6ff', rango: '' };
const escSinLead = { nombre: 'Consulta', emoji: '🔵', color: '#2563eb', dark: '#1d4ed8', bg: '#eff6ff', rango: '' };
const fuera = { nombre: 'Consulta', emoji: '🔵', color: '#2563eb', dark: '#1d4ed8', bg: '#eff6ff', rango: '' };
const t = hasLead ? (temas[norm(categoria)] || neutro) : (escalated ? escSinLead : fuera);

let pts = parseInt(puntaje, 10);
if (isNaN(pts)) pts = null; else pts = Math.max(0, Math.min(100, pts));

const etiqueta = (hasLead && temas[norm(categoria)]) ? 'Lead ' + t.nombre : 'Consulta';
const titulo = etiqueta;

const asunto = t.emoji + ' ' + etiqueta + (hasLead ? ' | ' + nombre + (pts !== null ? ' | ' + pts + ' pts' : '') : '') + (escalated ? ' | ESCALAR' : '');

// ---------- Texto plano (respaldo) ----------
const bloqueLead = hasLead
  ? [
      'DATOS DEL LEAD', linea,
      'Nombre: ' + nombre,
      'Email: ' + email,
      'Telefono: ' + telefono,
      'Empresa: ' + empresa,
      'Necesidad: ' + necesidad,
      'Presupuesto: ' + presupuesto,
      'Plazo: ' + plazo,
      '',
      'CALIFICACION', linea,
      'Categoria: ' + categoria,
      'Puntaje: ' + puntaje,
      'Escalar a humano: ' + escalarLead,
      'Notas: ' + notas,
    ].join('\n')
  : 'DATOS DEL LEAD\n' + linea + '\nEl agente no registro ningun lead en esta conversacion.\nEmail en el mensaje: ' + (emailMsg || 'no informado') + '\nTelefono en el mensaje: ' + (telMsg || 'no informado');

const logAuditoria = [
  titulo.toUpperCase() + (escalated ? ' - REQUIERE CONTACTO HUMANO' : ''),
  '',
  'Fecha: ' + fechaLocal + ' (hora de Chile)',
  'Sesion: ' + (chat.sessionId ?? 'n/d'),
  '',
  bloqueLead,
  '',
  'MENSAJE DEL USUARIO', linea,
  chat.chatInput ?? '(vacio)',
  '',
  'RESPUESTA DEL AGENTE', linea,
  agent.output ?? '(sin respuesta)',
  '',
  'Herramientas ejecutadas: ' + steps.length,
].join('\n');

// ---------- HTML ----------
const seccion = (x) =>
  '<div style="margin:24px 0 8px;font-size:12px;font-weight:bold;letter-spacing:1px;color:#6b7280;">' + esc(x.toUpperCase()) + '</div>';

const fila = (k, valorHtml) =>
  '<tr><td style="padding:8px 12px;color:#6b7280;font-size:13px;width:120px;vertical-align:top;border-bottom:1px solid #f0f0f0;">' + esc(k) + '</td>'
  + '<td style="padding:8px 12px;color:#111827;font-size:14px;border-bottom:1px solid #f0f0f0;">' + valorHtml + '</td></tr>';

const emailHtml = email.includes('@') ? '<a href="mailto:' + esc(email) + '" style="color:#2563eb;">' + esc(email) + '</a>' : esc(email);
const telHtml = /\d{6,}/.test(telefono) ? '<a href="tel:' + esc(telefono.replace(/[^+\d]/g, '')) + '" style="color:#2563eb;">' + esc(telefono) + '</a>' : esc(telefono);

const caja = (texto) =>
  '<div style="background:#f9fafb;border-left:4px solid #d1d5db;padding:10px 14px;font-size:14px;color:#374151;line-height:1.5;">' + br(texto) + '</div>';

const bloquePuntaje = pts === null ? '' :
  '<div style="margin-top:20px;padding:14px 16px;background:' + t.bg + ';border:1px solid ' + t.color + ';border-radius:8px;">'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>'
  + '<td style="font-size:32px;font-weight:bold;color:' + t.dark + ';">' + pts + '<span style="font-size:16px;color:#6b7280;font-weight:normal;"> / 100</span></td>'
  + '<td align="right" style="font-size:13px;font-weight:bold;color:' + t.dark + ';">' + esc(t.nombre.toUpperCase())
  + (t.rango ? '<br><span style="font-weight:normal;color:#6b7280;">Rango ' + t.rango + ' pts</span>' : '') + '</td>'
  + '</tr></table>'
  + '<div style="background:#e5e7eb;border-radius:6px;height:10px;margin-top:10px;"><div style="background:' + t.color + ';height:10px;border-radius:6px;width:' + pts + '%;"></div></div>'
  + '</div>';

const cuerpoLead = hasLead
  ? bloquePuntaje
    + seccion('Datos del lead')
    + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;border:1px solid #f0f0f0;">'
    + fila('Nombre', '<strong>' + esc(nombre) + '</strong>')
    + fila('Email', emailHtml)
    + fila('Teléfono', telHtml)
    + fila('Empresa', esc(empresa))
    + fila('Necesidad', esc(necesidad))
    + fila('Presupuesto', esc(presupuesto))
    + fila('Plazo', esc(plazo))
    + '</table>'
    + seccion('Notas comerciales')
    + caja(notas)
  : seccion('Datos del lead') + caja('El agente no registró ningún lead en esta conversación.\nEmail en el mensaje: ' + (emailMsg || 'no informado') + '\nTeléfono en el mensaje: ' + (telMsg || 'no informado'));

const bannerAccion = escalated
  ? '<div style="background:#111827;color:#ffffff;padding:10px 24px;font-size:13px;font-weight:bold;letter-spacing:0.5px;">'
    + (hasLead ? 'ACCIÓN REQUERIDA: contactar a este lead a la brevedad' : 'ACCIÓN REQUERIDA: una persona del equipo debe revisar esta conversación')
    + '</div>'
  : '';

const html =
  '<div style="background:#f3f4f6;padding:24px 12px;font-family:Arial,Helvetica,sans-serif;">'
  + '<div style="max-width:620px;margin:0 auto;background:#ffffff;border:1px solid #e5e7eb;border-radius:8px;overflow:hidden;">'
  + '<div style="background:' + t.dark + ';color:#ffffff;padding:20px 24px;">'
  + '<div style="font-size:16px;font-weight:bold;letter-spacing:3px;">NEXA DIGITAL</div>'
  + '<div style="font-size:11px;letter-spacing:1px;opacity:0.85;margin-top:2px;">AGENTE DE CALIFICACIÓN DE LEADS</div>'
  + '<div style="font-size:26px;font-weight:bold;margin-top:6px;">' + esc(titulo) + '</div>'
  + (hasLead ? '<div style="font-size:15px;margin-top:4px;opacity:0.95;">' + esc(nombre) + '</div>' : '')
  + '</div>'
  + bannerAccion
  + '<div style="padding:8px 24px 24px;">'
  + cuerpoLead
  + seccion('Mensaje del usuario') + caja(chat.chatInput ?? '(vacío)')
  + seccion('Respuesta del agente') + caja(agent.output ?? '(sin respuesta)')
  + '<div style="margin-top:24px;padding-top:12px;border-top:1px solid #f0f0f0;font-size:12px;color:#9ca3af;">'
  + esc(fechaLocal) + ' (hora de Chile) · Sesión ' + esc(chat.sessionId ?? 'n/d') + ' · Herramientas ejecutadas: ' + steps.length
  + '</div>'
  + '</div></div></div>';

return [{
  json: {
    output: agent.output,
    sessionId: chat.sessionId,
    herramientasUsadas: steps.length,
    requiereAtencionHumana: escalated,
    hasLead,
    mensaje: msgUsuario,
    emailMsg,
    telMsg,
    fechaISO: new Date().toISOString(),
    respuestaAgente: String(agent.output ?? ''),
    asunto,
    logAuditoria,
    html,
  },
}];

// Suma el intercambio actual al historial de la sesión y decide si hay que resumir (> 5 mensajes).
let ctx;
try { ctx = $('Contexto Usuario Existente').first().json; } catch (e) { ctx = $('Contexto Usuario Nuevo').first().json; }
const log = $('Preparar Log de Control').first().json;

const MARCA = '(Historial compactado en Last_Summary)';
let historial = String(ctx.historial ?? '');
if (historial.trim() === MARCA) historial = '';
const turno = `[${log.fechaISO}]\nUsuario: ${log.mensaje}\nAgente: ${log.respuestaAgente}`;
historial = historial ? historial + '\n\n' + turno : turno;

const message_count = (Number(ctx.message_count) || 0) + 1;

let status = 'En curso';
if (log.hasLead) status = 'Lead registrado';
else if (log.requiereAtencionHumana) status = 'Escalado a humano';
else if (['Lead registrado', 'Escalado a humano'].includes(ctx.status)) status = ctx.status;

return [{
  json: {
    session_id: ctx.session_id,
    historial,
    message_count,
    status,
    last_summary_raw: ctx.last_summary_raw || '',
    debe_resumir: message_count > 5,
  },
}];

// Valida que el modelo mini haya devuelto exactamente { asunto_principal, puntos_clave, accion_requerida }.
// Si la salida no es válida, conserva el resumen anterior y no borra el historial (se reintenta en el próximo turno).
const prev = $('Actualizar Contador e Historial').first().json;
const raw = String($input.first().json.text ?? '').replace(/^```(?:json)?\s*|\s*```$/g, '').trim();

let obj = null;
try { obj = JSON.parse(raw); } catch (e) { obj = null; }

const valido = !!obj
  && typeof obj.asunto_principal === 'string'
  && Array.isArray(obj.puntos_clave)
  && typeof obj.accion_requerida === 'string';

if (!valido) {
  return [{ json: { ...prev, resumen_valido: false, last_summary: prev.last_summary_raw,
                    historial_final: prev.historial, message_count_final: prev.message_count } }];
}

const resumen = {
  asunto_principal: obj.asunto_principal.trim(),
  puntos_clave: obj.puntos_clave.map((p) => String(p).trim()).filter(Boolean).slice(0, 6),
  accion_requerida: obj.accion_requerida.trim(),
};

return [{ json: { ...prev, resumen_valido: true, last_summary: JSON.stringify(resumen),
                  historial_final: '(Historial compactado en Last_Summary)', message_count_final: 0 } }];
